import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { requirePersona } from '@/lib/auth/require-persona'
import { InventoryHub } from '@/components/inventory/InventoryHub'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'

export const metadata: Metadata = {
  title: 'Inventory — InkOS',
}

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export default async function InventoryPage({ searchParams }: Props) {
  await requirePersona(['studio_owner'])
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const params = await searchParams
  const category = typeof params.category === 'string' ? params.category : undefined

  return (
    <PageShell>
      <PageHeader
        title="Inventory"
        description="Track consumables, manage suppliers, and monitor stock levels."
      />

      <Suspense fallback={<div className="flex-1 animate-pulse bg-muted/20 rounded-xl min-h-[200px]" />}>
        <InventoryHub defaultCategory={category} />
      </Suspense>
    </PageShell>
  )
}

import { cn } from '@/lib/utils'

interface StockLevelBadgeProps {
  current: number
  min: number
  className?: string | undefined
}

export function StockLevelBadge({ current, min, className }: StockLevelBadgeProps) {
  // State 1: at or below minimum — Rust filled
  const isCritical = current <= min && min > 0
  // State 2: within 25% above minimum — Rust outlined
  const isWarning = !isCritical && min > 0 && current <= min * 1.25
  // State 3: healthy — Stone outlined

  return (
    <span
      className={cn(
        'inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-medium tabular-nums border',
        isCritical && 'bg-rust text-background border-rust',
        isWarning && !isCritical && 'bg-transparent text-rust border-rust',
        !isCritical && !isWarning && 'bg-transparent text-foreground border-stone-brand',
        className,
      )}
    >
      {current} / min {min}
    </span>
  )
}

