'use client'

import { useState, useCallback } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
  TooltipProvider,
} from '@/components/ui/tooltip'
import { Input } from '@/components/ui/input'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Badge } from '@/components/ui/badge'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { TableSkeleton } from '@/components/skeletons'
import { StockLevelBadge } from '@/components/inventory/StockLevelBadge'
import { CategoryBadge } from '@/components/inventory/CategoryBadge'
import { ItemForm } from '@/components/inventory/ItemForm'
import { StockAdjustmentModal } from '@/components/inventory/StockAdjustmentModal'
import { formatCurrency, cn } from '@/lib/utils'
import { queryKeys } from '@/lib/query-keys'
import { toast } from 'sonner'
import {
  MoreHorizontal,
  Plus,
  Search,
  Package,
  Truck,
  AlertCircle,
  Archive,
  Edit,
  Minus,
  ExternalLink,
  Upload,
  ShieldCheck,
  ShieldOff,
} from 'lucide-react'
import type { Tables } from '@/lib/supabase/types'

type InventoryItem = Tables<'inventory_items'>
type InkRegistry = Tables<'studio_ink_registry'>

type ItemWithRelations = InventoryItem & {
  suppliers: { id: string; name: string } | null
  locations: { id: string; name: string } | null
  ink_registry: Pick<
    InkRegistry,
    'id' | 'batch_number' | 'manufacture_date' | 'expiry_date' | 'reach_compliant' | 'sds_url'
  > | null
}

type SortParam = 'value' | 'name' | 'stock'

interface FilterChipProps {
  icon: React.ReactNode
  label: string
  value: string
  onValueChange: (v: string) => void
  children: React.ReactNode
  placeholder: string
}

function FilterChip({ icon, label, value, onValueChange, children, placeholder }: FilterChipProps) {
  const isActive = value !== 'all'
  return (
    <Select value={value} onValueChange={(v) => { if (v !== null) onValueChange(v) }}>
      <SelectTrigger
        className={cn(
          'h-8 gap-1.5 border-border text-xs',
          isActive
            ? 'border-foreground text-foreground font-medium'
            : 'text-muted-foreground',
        )}
      >
        {icon}
        <span className="hidden sm:inline">{label}:</span>
        <SelectValue placeholder={placeholder} />
      </SelectTrigger>
      <SelectContent>
        {children}
      </SelectContent>
    </Select>
  )
}

function ExpiryBadge({ expiryDate }: { expiryDate: string | null }) {
  if (!expiryDate) {
    return <span className="text-xs text-muted-foreground">—</span>
  }

  const now = new Date()
  const expiry = new Date(expiryDate)
  const daysUntil = Math.ceil((expiry.getTime() - now.getTime()) / (1000 * 60 * 60 * 24))
  const isExpired = daysUntil <= 0
  const isSoonExpiring = !isExpired && daysUntil < 90

  return (
    <span
      className={cn(
        'inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-medium tabular-nums border',
        isExpired && 'bg-rust text-background border-rust',
        isSoonExpiring && !isExpired && 'bg-transparent text-rust border-rust',
        !isExpired && !isSoonExpiring && 'bg-transparent text-muted-foreground border-stone-brand',
      )}
    >
      {expiryDate.slice(0, 10)}
      {isExpired && ' · expired'}
      {isSoonExpiring && !isExpired && ` · ${daysUntil}d`}
    </span>
  )
}

function ReachPill({ compliant }: { compliant: boolean }) {
  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger>
          <span
            className={cn(
              'inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[11px] font-medium border cursor-default',
              compliant
                ? 'bg-transparent text-foreground border-stone-brand'
                : 'bg-transparent text-rust border-rust',
            )}
          >
            {compliant ? (
              <ShieldCheck className="h-3 w-3" />
            ) : (
              <ShieldOff className="h-3 w-3" />
            )}
            {compliant ? 'REACH' : 'Non-compliant'}
          </span>
        </TooltipTrigger>
        <TooltipContent side="top">
          EU REACH compliance — required if you ship or apply ink to clients in the EU
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  )
}

interface ItemsTableProps {
  defaultCategory?: string | undefined
}

export function ItemsTable({ defaultCategory }: ItemsTableProps) {
  const queryClient = useQueryClient()
  const [search, setSearch] = useState('')
  const [categoryFilter, setCategoryFilter] = useState(defaultCategory ?? 'all')
  const [supplierFilter, setSupplierFilter] = useState('all')
  const [stockFilter, setStockFilter] = useState('all')
  const [sortParam, setSortParam] = useState<SortParam>('name')
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [editItem, setEditItem] = useState<ItemWithRelations | null>(null)
  const [adjustItem, setAdjustItem] = useState<ItemWithRelations | null>(null)

  const isInkFilter = categoryFilter === 'ink'

  const params = new URLSearchParams()
  if (categoryFilter !== 'all') params.set('category', categoryFilter)
  if (stockFilter !== 'all') params.set('stock_status', stockFilter)
  if (isInkFilter) params.set('include', 'ink_registry')
  if (sortParam === 'value') params.set('sort', 'value')

  const { data, isLoading, error } = useQuery({
    queryKey: queryKeys.inventory.items({ category: categoryFilter, stock_status: stockFilter, sort: sortParam }),
    queryFn: async () => {
      const res = await fetch(`/api/inventory/items?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to fetch items')
      const json = await res.json() as { data: ItemWithRelations[] }
      return json.data
    },
  })

  // Supplier list for filter chip
  const { data: suppliersData } = useQuery({
    queryKey: queryKeys.inventory.suppliers(),
    queryFn: async () => {
      const res = await fetch('/api/inventory/suppliers')
      if (!res.ok) throw new Error('Failed to fetch suppliers')
      const json = await res.json() as { data: Array<{ id: string; name: string }> }
      return json.data
    },
  })

  const archiveMutation = useMutation({
    mutationFn: async (id: string) => {
      const res = await fetch(`/api/inventory/items/${id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to archive item')
    },
    onSuccess: () => {
      toast.success('Item archived')
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.items() })
    },
    onError: () => toast.error('Failed to archive item'),
  })

  const handleCategoryChange = useCallback((v: string) => {
    setCategoryFilter(v)
  }, [])

  const clearFilters = useCallback(() => {
    setSearch('')
    setCategoryFilter('all')
    setSupplierFilter('all')
    setStockFilter('all')
  }, [])

  const hasActiveFilters =
    search !== '' || categoryFilter !== 'all' || supplierFilter !== 'all' || stockFilter !== 'all'

  return (
    <>
      {/* Filters */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-1 items-center gap-2 flex-wrap">
          <div className="relative flex-1 max-w-xs min-w-[160px]">
            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search items..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-8 h-8"
            />
          </div>

          {/* Category FilterChip */}
          <FilterChip
            icon={<Package className="h-3.5 w-3.5 shrink-0" />}
            label="Category"
            value={categoryFilter}
            onValueChange={handleCategoryChange}
            placeholder="All"
          >
            <SelectItem value="all">All Categories</SelectItem>
            <SelectItem value="ink">Ink</SelectItem>
            <SelectItem value="needle">Needle</SelectItem>
            <SelectItem value="supply">Supply</SelectItem>
            <SelectItem value="aftercare">Aftercare</SelectItem>
            <SelectItem value="equipment">Equipment</SelectItem>
            <SelectItem value="apparel">Apparel</SelectItem>
            <SelectItem value="other">Other</SelectItem>
          </FilterChip>

          {/* Supplier FilterChip */}
          <FilterChip
            icon={<Truck className="h-3.5 w-3.5 shrink-0" />}
            label="Supplier"
            value={supplierFilter}
            onValueChange={setSupplierFilter}
            placeholder="All"
          >
            <SelectItem value="all">All Suppliers</SelectItem>
            {(suppliersData ?? []).map((s) => (
              <SelectItem key={s.id} value={s.id}>{s.name}</SelectItem>
            ))}
          </FilterChip>

          {/* Stock FilterChip */}
          <FilterChip
            icon={<AlertCircle className="h-3.5 w-3.5 shrink-0" />}
            label="Stock"
            value={stockFilter}
            onValueChange={setStockFilter}
            placeholder="All"
          >
            <SelectItem value="all">All Stock</SelectItem>
            <SelectItem value="low">Low Stock</SelectItem>
            <SelectItem value="out">Out of Stock</SelectItem>
          </FilterChip>
        </div>

        <Button
          size="sm"
          onClick={() => { setEditItem(null); setDrawerOpen(true) }}
          className="shrink-0"
        >
          <Plus className="mr-1.5 h-4 w-4" />
          Add Item
        </Button>
      </div>

      <DataState
        data={data}
        isLoading={isLoading}
        isError={!!error}
        error={error instanceof Error ? error : null}
        loadingSlot={<TableSkeleton rows={6} />}
        emptySlot={
          hasActiveFilters ? (
            <EmptyState
              icon={Package}
              title="No items match your filters"
              description="Try adjusting your search or category filters."
              variant="no-results"
              cta={{ label: 'Clear filters', onClick: clearFilters }}
            />
          ) : (
            <EmptyState
              icon={Package}
              title="No inventory items yet"
              description="Add your first inventory item to start tracking stock and COGS."
              variant="first-time"
              cta={{ label: 'Add Item', onClick: () => { setEditItem(null); setDrawerOpen(true) } }}
            />
          )
        }
      >
        {(items) => {
          const filtered = items.filter((item) => {
            if (search) {
              const q = search.toLowerCase()
              const matchesSearch = (
                item.name.toLowerCase().includes(q) ||
                item.sku?.toLowerCase().includes(q) ||
                item.brand?.toLowerCase().includes(q)
              )
              if (!matchesSearch) return false
            }
            if (supplierFilter !== 'all' && item.supplier_id !== supplierFilter) {
              return false
            }
            return true
          })

          if (filtered.length === 0) {
            return (
              <EmptyState
                icon={Package}
                title="No items match your search"
                description="Try a different search term."
                variant="no-results"
              />
            )
          }

          return (
            <div className="rounded-lg border border-border overflow-hidden">
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow className="bg-muted/30 hover:bg-muted/30">
                      <TableHead className="text-xs">Name</TableHead>
                      <TableHead className="text-xs">Category</TableHead>
                      <TableHead className="text-xs">Brand</TableHead>
                      <TableHead className="text-xs text-right">Stock</TableHead>
                      <TableHead className="text-xs text-right">
                        <button
                          type="button"
                          className="flex items-center gap-1 ml-auto hover:text-foreground transition-colors"
                          onClick={() => setSortParam(sortParam === 'value' ? 'name' : 'value')}
                          aria-label="Sort by total value"
                        >
                          Total Value
                          {sortParam === 'value' && <span className="text-[10px]">↓</span>}
                        </button>
                      </TableHead>
                      <TableHead className="text-xs">Supplier</TableHead>
                      {/* Ink-only columns */}
                      {isInkFilter && (
                        <>
                          <TableHead className="text-xs">Batch</TableHead>
                          <TableHead className="text-xs">Expiry</TableHead>
                          <TableHead className="text-xs">SDS</TableHead>
                        </>
                      )}
                      <TableHead className="text-xs w-[90px] text-right">Action</TableHead>
                      <TableHead className="w-10" />
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {filtered.map((item) => {
                      const isBelowMin = item.current_stock < item.min_threshold && item.min_threshold > 0
                      const costCents = item.cost_per_unit_cents ?? 0
                      const stockValue = costCents * Number(item.current_stock)

                      return (
                        <TableRow key={item.id} className="group">
                          <TableCell>
                            <div className="flex flex-col gap-0.5">
                              <span className="text-sm font-medium">{item.name}</span>
                              {item.sku && (
                                <span className="text-[11px] font-mono text-muted-foreground">
                                  {item.sku}
                                </span>
                              )}
                            </div>
                          </TableCell>
                          <TableCell>
                            <CategoryBadge category={item.category} />
                          </TableCell>
                          <TableCell>
                            <span className="text-sm text-muted-foreground">
                              {item.brand ?? '—'}
                            </span>
                          </TableCell>
                          <TableCell className="text-right">
                            <StockLevelBadge
                              current={Number(item.current_stock)}
                              min={Number(item.min_threshold)}
                            />
                          </TableCell>
                          <TableCell className="text-right text-xs tabular-nums text-muted-foreground whitespace-nowrap">
                            {formatCurrency(costCents)}
                            <span className="mx-1 text-border">·</span>
                            <span className="text-foreground font-medium">{formatCurrency(stockValue)}</span>
                          </TableCell>
                          <TableCell>
                            <span className="text-sm text-muted-foreground">
                              {/* Supplier renders name (not UUID) — data comes from join */}
                              {item.suppliers?.name ?? '—'}
                            </span>
                          </TableCell>

                          {/* Ink-only columns */}
                          {isInkFilter && (
                            <>
                              <TableCell>
                                {item.ink_registry?.batch_number ? (
                                  <span className="font-mono text-[13px] text-muted-foreground tabular-nums">
                                    {item.ink_registry.batch_number}
                                  </span>
                                ) : (
                                  <span className="text-xs text-muted-foreground">—</span>
                                )}
                              </TableCell>
                              <TableCell>
                                <ExpiryBadge expiryDate={item.ink_registry?.expiry_date ?? null} />
                              </TableCell>
                              <TableCell>
                                {item.ink_registry ? (
                                  <div className="flex flex-col gap-1">
                                    <ReachPill compliant={item.ink_registry.reach_compliant} />
                                    {item.ink_registry.sds_url ? (
                                      <a
                                        href={item.ink_registry.sds_url}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="inline-flex items-center gap-1 text-[11px] text-muted-foreground hover:text-foreground transition-colors"
                                      >
                                        <ExternalLink className="h-3 w-3" />
                                        View SDS
                                      </a>
                                    ) : (
                                      <button
                                        type="button"
                                        className="inline-flex items-center gap-1 text-[11px] text-muted-foreground border border-dashed border-stone-brand rounded px-1.5 py-0.5 hover:text-foreground hover:border-foreground transition-colors"
                                        onClick={() => {
                                          // SDS upload — wired to POST /api/inventory/ink-registry/[id]/sds (Sprint 2 backend)
                                          toast.info('SDS upload coming soon')
                                        }}
                                      >
                                        <Upload className="h-3 w-3" />
                                        + Upload SDS
                                      </button>
                                    )}
                                  </div>
                                ) : (
                                  <span className="text-xs text-muted-foreground">—</span>
                                )}
                              </TableCell>
                            </>
                          )}

                          {/* Action column: Reorder (Rust outlined) or Adjust (Stone outlined) */}
                          <TableCell className="text-right">
                            {isBelowMin ? (
                              <Button
                                variant="outline"
                                size="sm"
                                className="h-7 text-xs border-rust text-rust hover:bg-rust hover:text-background"
                                onClick={() => setAdjustItem(item)}
                              >
                                Reorder
                              </Button>
                            ) : (
                              <Button
                                variant="outline"
                                size="sm"
                                className="h-7 text-xs border-stone-brand text-muted-foreground hover:text-foreground"
                                onClick={() => setAdjustItem(item)}
                              >
                                Adjust
                              </Button>
                            )}
                          </TableCell>

                          {/* Overflow menu */}
                          <TableCell>
                            <DropdownMenu>
                              <DropdownMenuTrigger render={
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  className="h-7 w-7 opacity-0 group-hover:opacity-100"
                                >
                                  <MoreHorizontal className="h-4 w-4" />
                                </Button>
                              } />
                              <DropdownMenuContent align="end">
                                <DropdownMenuItem
                                  onClick={() => { setEditItem(item); setDrawerOpen(true) }}
                                >
                                  <Edit className="mr-2 h-4 w-4" />
                                  Edit
                                </DropdownMenuItem>
                                <DropdownMenuItem
                                  onClick={() => setAdjustItem(item)}
                                >
                                  <Minus className="mr-2 h-4 w-4" />
                                  Adjust Stock
                                </DropdownMenuItem>
                                <DropdownMenuItem
                                  className="text-destructive focus:text-destructive"
                                  onClick={() => archiveMutation.mutate(item.id)}
                                >
                                  <Archive className="mr-2 h-4 w-4" />
                                  Archive
                                </DropdownMenuItem>
                              </DropdownMenuContent>
                            </DropdownMenu>
                          </TableCell>
                        </TableRow>
                      )
                    })}
                  </TableBody>
                </Table>
              </div>
            </div>
          )
        }}
      </DataState>

      <ItemForm
        open={drawerOpen}
        onOpenChange={setDrawerOpen}
        item={editItem}
        onSuccess={() => {
          void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.items() })
        }}
      />

      {adjustItem && (
        <StockAdjustmentModal
          open={true}
          onOpenChange={(open) => { if (!open) setAdjustItem(null) }}
          item={adjustItem}
          onSuccess={() => {
            void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.items() })
            void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.movements() })
          }}
        />
      )}
    </>
  )
}

